-<!DOCTYPE html>
-<!-- SPDX-License-Identifier: Apache-2.0 -->
-<!--
-  FlatBars Lab — cross-engine compare. One template + data, rendered by Handlebars,
-  Stem, and FlatBars at once, side by side, with an agreement indicator. Reuses
-  the same engine adapters as the IDE (the shared seam); this is the "one
-  playground serves them all" breadth view that complements the deep IDE
-  (index.html). No CodeMirror/CDN — plain editors so it loads offline.
--->
-<html lang="en">
-<head>
-  <meta charset="utf-8" />
-  <meta name="viewport" content="width=device-width, initial-scale=1" />
-  <title>FlatBars Lab — cross-engine compare</title>
-  <style>
-    :root { --bg:#0f1115; --panel:#171a21; --line:#272b35; --fg:#e6e8ec; --muted:#8b929e; --accent:#7c9cff; --ok:#3fb950; --bad:#f85149; --warn:#d29922; --mono:ui-monospace,"SF Mono",Menlo,Consolas,monospace; }
-    * { box-sizing:border-box; }
-    body { margin:0; font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif; background:var(--bg); color:var(--fg); height:100vh; display:flex; flex-direction:column; }
-    header.bar { display:flex; align-items:center; gap:.8rem; padding:0 1rem; height:52px; background:var(--panel); border-bottom:1px solid var(--line); flex:0 0 auto; }
-    .wm { font-family:var(--mono); font-weight:700; font-size:1.1rem; }
-    .wm b { color:var(--accent); }
-    .agree { margin-left:auto; font-family:var(--mono); font-size:.8rem; padding:.2rem .6rem; border-radius:6px; border:1px solid var(--line); }
-    .agree.ok { color:var(--ok); border-color:var(--ok); }
-    .agree.differ { color:var(--warn); border-color:var(--warn); }
-    main { flex:1; display:grid; grid-template-rows:minmax(120px,30%) 1fr; min-height:0; }
-    .editors { display:grid; grid-template-columns:2fr 1fr; border-bottom:1px solid var(--line); min-height:0; }
-    .editors .pane, .out-pane { display:flex; flex-direction:column; min-height:0; min-width:0; }
-    .head { font-family:var(--mono); font-size:.74rem; text-transform:uppercase; letter-spacing:.06em; color:var(--muted); padding:.4rem .7rem; border-bottom:1px solid var(--line); background:var(--panel); display:flex; align-items:center; gap:.5rem; }
-    .head .ver { color:var(--muted); text-transform:none; letter-spacing:0; font-weight:400; }
-    .head .status { margin-left:auto; width:9px; height:9px; border-radius:50%; background:var(--muted); }
-    .head .status.ok { background:var(--ok); } .head .status.bad { background:var(--bad); }
-    textarea { flex:1; resize:none; border:0; outline:0; background:var(--bg); color:var(--fg); font-family:var(--mono); font-size:13px; line-height:1.5; padding:.7rem; }
-    .editors .pane:first-child { border-right:1px solid var(--line); }
-    .outputs { display:grid; grid-template-columns:repeat(3,1fr); min-height:0; }
-    .out-pane { border-right:1px solid var(--line); }
-    .out-pane:last-child { border-right:0; }
-    pre.out { margin:0; flex:1; overflow:auto; padding:.7rem; font-family:var(--mono); font-size:12.5px; line-height:1.5; white-space:pre-wrap; word-break:break-word; }
-    pre.out.err { color:var(--bad); }
-    pre.out.diff { background:rgba(210,153,34,.06); }
-  </style>
-</head>
-<body>
-  <header class="bar">
-    <span class="wm">flatbars<b>·</b>lab <span class="ver" style="font-size:.8rem;color:var(--muted)">cross-engine compare</span></span>
-    <span id="agree" class="agree">—</span>
-  </header>
-  <main>
-    <div class="editors">
-      <div class="pane">
-        <div class="head">Template</div>
-        <textarea id="tmpl" spellcheck="false"></textarea>
-      </div>
-      <div class="pane">
-        <div class="head">Data (JSON)</div>
-        <textarea id="data" spellcheck="false"></textarea>
-      </div>
-    </div>
-    <div class="outputs" id="outputs"></div>
-  </main>
-
-  <script type="module">
-    import { createRenderer } from "./stem.mjs";
-    import { createFlatBarsRenderer } from "./flatbars.mjs";
-
-    const byId = (id) => document.getElementById(id);
-    const escapeHtml = (s) => s.replace(/[&<>]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" }[c]));
-
-    // Each engine: { id, label, renderer }. Stem needs its wasm bytes; the JS
-    // engines initialise synchronously behind the same async create… seam.
-    const WASM = "./wasm/stem_native_bg.wasm";
-    const engines = [];
-    async function init() {
-      const defs = [
-        { id: "stem", label: "Stem", make: async () => createRenderer(await (await fetch(WASM)).arrayBuffer()) },
-        { id: "rawbars", label: "RawBars", make: () => createFlatBarsRenderer("core") },
-        { id: "fullbars", label: "FullBars", make: () => createFlatBarsRenderer("surface") },
-        { id: "maxbars", label: "MaxBars", make: () => createFlatBarsRenderer("maxbars") },
-      ];
-      const out = byId("outputs");
-      for (const d of defs) {
-        let renderer = null, err = null;
-        try { renderer = await d.make(); } catch (e) { err = e && e.message ? e.message : String(e); }
-        engines.push({ ...d, renderer, initError: err });
-        const pane = document.createElement("div");
-        pane.className = "out-pane";
-        pane.innerHTML =
-          `<div class="head">${d.label}<span class="ver" id="ver-${d.id}"></span><span class="status" id="st-${d.id}"></span></div>` +
-          `<pre class="out" id="out-${d.id}"></pre>`;
-        out.appendChild(pane);
-        if (renderer) byId(`ver-${d.id}`).textContent = " v" + renderer.version;
-      }
-    }
-
-    // Render the current template+data through one engine → { ok, text }.
-    function renderOne(eng, src, data) {
-      if (!eng.renderer) return { ok: false, text: "engine unavailable: " + (eng.initError || "?") };
-      try {
-        const c = eng.renderer.compile(src, {});
-        if (c && c.errors) return { ok: false, text: c.errors.map((e) => e.message).join("\n") };
-        const o = eng.renderer.render(c.program, data);
-        return { ok: true, text: typeof o === "string" ? o : (o && o.output) || "" };
-      } catch (e) {
-        return { ok: false, text: (e && e.message ? e.message : String(e)) };
-      }
-    }
-
-    function run() {
-      const src = byId("tmpl").value;
-      let data, dataErr = null;
-      try { data = JSON.parse(byId("data").value || "null"); } catch (e) { dataErr = "Data JSON error: " + e.message; }
-      const results = engines.map((eng) => {
-        const r = dataErr ? { ok: false, text: dataErr } : renderOne(eng, src, data);
-        return { eng, ...r };
-      });
-      // agreement: do all OK engines produce the same output?
-      const oks = results.filter((r) => r.ok);
-      const distinct = new Set(oks.map((r) => r.text));
-      const allAgree = oks.length === results.length && distinct.size === 1;
-      const agree = byId("agree");
-      agree.className = "agree " + (results.every((r) => r.ok) ? (allAgree ? "ok" : "differ") : "differ");
-      agree.textContent = results.every((r) => r.ok)
-        ? (allAgree ? "✓ all engines agree" : `differ — ${distinct.size} distinct outputs`)
-        : "errors present";
-      for (const r of results) {
-        const pre = byId(`out-${r.eng.id}`);
-        pre.className = "out" + (r.ok ? "" : " err") + (r.ok && !allAgree && distinct.size > 1 ? " diff" : "");
-        pre.textContent = r.text;
-        const st = byId(`st-${r.eng.id}`);
-        st.className = "status " + (r.ok ? "ok" : "bad");
-      }
-    }
-
-    let timer = null;
-    const schedule = () => { clearTimeout(timer); timer = setTimeout(run, 150); };
-
-    await init();
-    byId("tmpl").value = "<h1>Hello {{name}}</h1>\n<ul>{{#each items}}<li>{{this}}</li>{{/each}}</ul>";
-    byId("data").value = '{ "name": "World", "items": ["a", "b"] }';
-    byId("tmpl").addEventListener("input", schedule);
-    byId("data").addEventListener("input", schedule);
-    run();
-    window.__braceLabCompareReady = true; // smoke-test signal
-  </script>
-</body>
-</html>

